# owner: platform
import unittest

from hourglass.gaps import find_gaps
from hourglass.models import Span

HOURS = Span(540, 1020)


class FindGapsTests(unittest.TestCase):
    def test_gap_between_spans(self):
        spans = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(
            find_gaps(spans, HOURS), ["gap 12:00-13:00 (60 min)"]
        )

    def test_edges_and_overlaps(self):
        spans = [Span(600, 700), Span(650, 800)]
        self.assertEqual(
            find_gaps(spans, HOURS),
            ["gap 09:00-10:00 (60 min)",
             "gap 13:20-17:00 (220 min)"],
        )

    def test_no_spans_is_one_gap(self):
        self.assertEqual(
            find_gaps([], HOURS), ["gap 09:00-17:00 (480 min)"]
        )

    def test_full_cover_has_no_gaps(self):
        self.assertEqual(find_gaps([HOURS], HOURS), [])

    def test_outside_hours_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(480, 600)], HOURS)
